/*kr.happy.study.asset.statistics.dao.statisticsDao.statisticsByPeriod*/
SELECT MONTH(import_date) AS periodValue, SUM(tbIn.quantity) AS amount FROM tb_product_info AS tbIn, tb_product_import AS tbIm WHERE tbIm.product_no = tbIn.product_no AND YEAR(import_date) = #{year}
AND tbIn.category_code = #{category}
GROUP BY MONTH(import_date) ORDER BY periodValue;
SELECT YEAR(import_date) AS periodValue, SUM(tbIn.quantity) AS amount FROM tb_product_info AS tbIn, tb_product_import AS tbIm WHERE tbIm.product_no = tbIn.product_no
AND tbIn.category_code = #{category}
GROUP BY YEAR(import_date) ORDER BY periodValue;

/*kr.happy.study.asset.statistics.dao.statisticsDao.statisticCanUse*/
SELECT MONTH(import_date) AS periodValue, SUM(tbIn.quantity) AS amount FROM tb_product_info AS tbIn, tb_product_detail AS tbDt, tb_product_import AS tbIm WHERE tbIn.product_no = tbDt.product_no AND tbIm.product_no = tbDt.product_no AND tbDt.product_state = 'Y' AND YEAR(import_date) = #{year}
AND tbIn.category_code = #{category}
GROUP BY MONTH(import_date) ORDER BY periodValue
SELECT YEAR(import_date) AS periodValue, SUM(tbIn.quantity) AS amount FROM tb_product_info AS tbIn, tb_product_detail AS tbDt, tb_product_import AS tbIm WHERE tbIn.product_no = tbDt.product_no AND tbIm.product_no = tbDt.product_no AND tbDt.product_state = 'Y'
AND tbIn.category_code = #{category}
GROUP BY YEAR(import_date) ORDER BY periodValue
